const { itemType, itemTypeName, getState } = options
const state = getState();
const hidden = state.grid.selectedRows.length < 2;
if (hidden) {
	return { hidden };
}

const isNew = state.grid.selectedRows.every(selectedRowId => ArasModules.item.isNew(itemTypeName, selectedRowId));
const isPolymorphicIT = ArasModules.metadata.itemType.isPolymorphic(itemType.id);
const isPromoteDisabled = window.isFunctionDisabled(itemTypeName, 'Promote');
const disabled = isNew || isPolymorphicIT || isPromoteDisabled;

return {
	disabled,
	hidden: false
};
